//! Action coverage (`-coverage`): per action, the states it generated and
//! the distinct states it found (TLC's action-level coverage statistics,
//! tlc2.tool.coverage.ActionWrapper: `Worker.addElement` counts a
//! successor as generated by its action before the constraints,
//! `isSeenState` counts it as found if it satisfies them and is new).
//!
//! Each worker counts into its own `Slot::cov` (written by it only, relaxed
//! loads and stores: no shared cache line per successor); the counts are
//! summed when read. The search counts only when `Options::coverage` is
//! on (the worker's hot path is instantiated without the counting
//! otherwise). With several workers, which action finds a state first is
//! a race: the search then chooses the representatives in BFS order
//! (`order`), so a state counts for the action that one worker would have
//! found it with, whatever the number of workers.

use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use super::Shared;
use crate::model::Model;

/// Coverage counts per action (index into `Model::action_names`).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Coverage {
    /// Initial states generated (including duplicates).
    pub init_generated: u64,
    /// Successor states generated by each action (including those already
    /// seen and those violating the constraints).
    pub generated: Vec<u64>,
    /// Distinct states found by each action (new states satisfying the
    /// constraints; a state found by several actions counts for the first
    /// in BFS order).
    pub distinct: Vec<u64>,
}

impl Coverage {
    /// The counts from flat counters (as `Slot::cov`: generated and
    /// distinct per action, interleaved).
    pub(super) fn from_flat(init_generated: u64, flat: &[u64]) -> Coverage {
        Coverage {
            init_generated,
            generated: flat.iter().step_by(2).copied().collect(),
            distinct: flat.iter().skip(1).step_by(2).copied().collect(),
        }
    }
}

/// Periodic coverage reports during the search (TLC prints the statistics
/// every `-coverage` minutes, and at the end).
#[derive(Clone)]
pub struct CoverageReport {
    /// Time of the first report after the start of the search.
    pub first: Duration,
    /// Interval between later reports.
    pub every: Duration,
    /// Called (on a monitor thread) with the counts so far.
    pub report: Arc<dyn Fn(&Coverage) + Send + Sync>,
}

impl std::fmt::Debug for CoverageReport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoverageReport").field("first", &self.first).field("every", &self.every).finish_non_exhaustive()
    }
}

/// The index of the generated count of action `a` in flat counters (the
/// distinct count follows it).
#[inline(always)]
pub(super) fn generated_at(a: u32) -> usize {
    2 * a as usize
}

/// Add one to counter `i` of a worker's own counters (an action index
/// outside them counts nowhere).
#[inline(always)]
pub(super) fn bump(counters: &[AtomicU64], i: usize) {
    if let Some(c) = counters.get(i) {
        c.store(c.load(Ordering::Relaxed) + 1, Ordering::Relaxed);
    }
}

/// The values of counters.
pub(super) fn load(counters: &[AtomicU64]) -> Vec<u64> {
    counters.iter().map(|c| c.load(Ordering::Relaxed)).collect()
}

/// Add `b` to `a` (flat counters; `a` grows as needed).
pub(super) fn add(a: &mut Vec<u64>, b: &[u64]) {
    if a.len() < b.len() {
        a.resize(b.len(), 0);
    }
    for (x, y) in a.iter_mut().zip(b) {
        *x += y;
    }
}

impl<M: Model> Shared<'_, M> {
    /// The coverage counts so far: those before the resume point the search
    /// resumed from, plus the workers'.
    pub(super) fn coverage(&self) -> Coverage {
        Coverage::from_flat(self.init_generated.load(Ordering::Relaxed), &self.coverage_counts())
    }

    /// `coverage`, flat (as `Slot::cov`).
    pub(super) fn coverage_counts(&self) -> Vec<u64> {
        let mut flat = self.cov_base.clone();
        for s in self.slots.iter() {
            add(&mut flat, &load(&s.cov));
        }
        flat
    }
}

/// Report the coverage at `c.first`, then every `c.every`, until `done`.
pub(super) fn coverage_monitor<M: Model>(shared: &Shared<'_, M>, c: &CoverageReport, done: &tlx_base::par::Done) {
    let mut next = c.first;
    tlx_base::par::every(Duration::from_millis(50), done, || {
        if shared.start.elapsed() >= next && !done.is_set() {
            (c.report)(&shared.coverage());
            next += c.every.max(Duration::from_millis(100));
        }
    });
}
